#!/usr/bin/env python3
"""Exact finite transformation monoid generated by elementary linear contexts.

The quotient of a finite observed algebra remembers the behaviorally distinct
states.  This module computes the dual operational object: the distinct
endomaps of that quotient generated by elementary polynomial translations.
"""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from itertools import product
from typing import Hashable, Mapping, Sequence

from compositional_crystal import Operation, crystallize_algebra

Element = Hashable
Output = Hashable


@dataclass(frozen=True)
class Generator:
    name: str
    action: tuple[int, ...]


@dataclass(frozen=True)
class ContextMonoid:
    fibers: tuple[tuple[Element, ...], ...]
    observations: tuple[Output, ...]
    generators: tuple[Generator, ...]
    transformations: tuple[tuple[int, ...], ...]
    shortest_words: tuple[tuple[int, ...], ...]
    witnesses: tuple[tuple[int, int, tuple[int, ...]], ...]

    def apply_word(self, state: int, word: Sequence[int]) -> int:
        for generator in word:
            state = self.generators[generator].action[state]
        return state


def _elementary_translations(
    elements: tuple[Element, ...], operations: tuple[Operation, ...]
) -> tuple[tuple[str, tuple[Element, ...]], ...]:
    translations = []
    for operation in operations:
        for slot in range(operation.arity):
            for fixed in product(elements, repeat=operation.arity - 1):
                values = []
                for value in elements:
                    args = list(fixed)
                    args.insert(slot, value)
                    values.append(operation.table[tuple(args)])
                label = f"{operation.name}[slot={slot},fixed={fixed!r}]"
                translations.append((label, tuple(values)))
    return tuple(translations)


def _then(left: tuple[int, ...], right: tuple[int, ...]) -> tuple[int, ...]:
    """Sequential composition: apply left, then right."""
    return tuple(right[left[state]] for state in range(len(left)))


def build_context_monoid(
    elements: Sequence[Element],
    operations: Sequence[Operation],
    observation: Mapping[Element, Output],
) -> ContextMonoid:
    """Crystallize an algebra and generate its effective context monoid."""
    xs = tuple(elements)
    ops = tuple(operations)
    element_index = {element: index for index, element in enumerate(xs)}
    crystal = crystallize_algebra(xs, ops, observation)
    class_of = {
        element: index
        for index, fiber in enumerate(crystal.fibers)
        for element in fiber
    }

    generators = []
    for name, translation in _elementary_translations(xs, ops):
        action = []
        for fiber in crystal.fibers:
            targets = {class_of[translation[element_index[element]]] for element in fiber}
            if len(targets) != 1:
                raise ValueError("contextual quotient is not translation-stable")
            action.append(next(iter(targets)))
        candidate = Generator(name, tuple(action))
        if candidate.action not in {generator.action for generator in generators}:
            generators.append(candidate)

    identity = tuple(range(len(crystal.fibers)))
    words: dict[tuple[int, ...], tuple[int, ...]] = {identity: ()}
    queue = deque((identity,))
    while queue:
        current = queue.popleft()
        for index, generator in enumerate(generators):
            successor = _then(current, generator.action)
            if successor not in words:
                words[successor] = words[current] + (index,)
                queue.append(successor)

    transformations = tuple(words)
    shortest_words = tuple(words[transformation] for transformation in transformations)

    witnesses = []
    for left in range(len(crystal.fibers)):
        for right in range(left + 1, len(crystal.fibers)):
            candidates = []
            for transformation, word in words.items():
                if (crystal.observations[transformation[left]]
                        != crystal.observations[transformation[right]]):
                    candidates.append(word)
            if not candidates:
                raise ValueError("distinct crystal states lack a separating context")
            witness = min(candidates, key=lambda word: (len(word), word))
            witnesses.append((left, right, witness))

    return ContextMonoid(
        crystal.fibers,
        crystal.observations,
        tuple(generators),
        transformations,
        shortest_words,
        tuple(witnesses),
    )
